// LFM3-as-emitter diagnosis (run 015): same v3 stratified selection and
// grounded prompt, generated by the local LFM3 server instead of Gemini.
// Measures grounded recall + ratio (LFM3 tokenizer via /tokenize — NOT
// comparable to Gemini-token ratios in absolute terms) + punt rate +
// tier-1 grounding fails + per-sample wall latency. New outputs:
// data/derived/lfm3-emit.jsonl + lfm3-emit-summary.json (v3 files untouched).
// The local server is free but slow: ~4 parallel slots.
// Run from worker/: node --experimental-strip-types scripts/lfm3-emit.ts [limit] [--force] [--shot]
// --shot (run 018 fix): 1-shot demo + </think> assistant prefill, which breaks
// LFM3's non-convergent deliberation loop. Local-only technique; outputs go to
// lfm3-emit-shot.* so the 0/25 baseline record stays intact.
// Requires: llama serve on 127.0.0.1:9931 (see run 013).
import {
	appendFileSync,
	mkdirSync,
	readFileSync,
	statSync,
	writeFileSync,
} from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { extractEntities } from '../src/entities.ts';
import { checkEntityGrounding } from '../src/grounding.ts';
import {
	percentile,
	recallByClass,
	type SampleScore,
	scoreGroundedSample,
	summarize,
} from '../src/ireval.ts';
import { loadStratified, type Sample } from './ir-pilot-v3.ts';

const LFM3_BASE = 'http://127.0.0.1:9931';
const CONCURRENCY = 4;
const TEMPERATURE = 0;
const MAX_IR_TOKENS = 256;
const MAX_ERROR_RATE = 0.1;
const FETCH_RETRIES = 2;
const PUNT_TEXT = 'insufficient grounding'; // ir-grounded-v1.md rule 3.

const sleep = (ms: number): Promise<void> =>
	new Promise((r) => setTimeout(r, ms));

interface EmitRow {
	key: string;
	reference: string;
	ir: string;
	fullTokens: number;
	irTokens: number;
	ratio: number;
	recall: number | null;
	missing: string[];
	classTotals: Record<string, number>;
	punt: boolean;
	tier1pass: boolean;
	tier1ungrounded: string[];
	wallMs: number;
	serverMs: number | null;
	error: string | null;
}

async function postJson(path: string, body: unknown): Promise<unknown> {
	let last = '';
	for (let attempt = 0; attempt <= FETCH_RETRIES; attempt++) {
		try {
			const res = await fetch(`${LFM3_BASE}${path}`, {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify(body),
			});
			if (!res.ok) {
				throw new Error(`http ${res.status}`);
			}
			return (await res.json()) as unknown;
		} catch (e) {
			last = e instanceof Error ? e.message : String(e);
			await sleep(1000);
		}
	}
	throw new Error(`lfm3 ${path} failed: ${last}`);
}

async function tokenize(text: string): Promise<number> {
	const out = (await postJson('/tokenize', { content: text })) as {
		tokens?: unknown;
	};
	if (!Array.isArray(out.tokens)) {
		throw new Error('lfm3 /tokenize shape changed');
	}
	return out.tokens.length;
}

function isPunt(ir: string): boolean {
	return ir.trim().toLowerCase() === PUNT_TEXT;
}

/** LFM3-only convergence fix (run 018): pre-closing the think tag breaks the
 * non-convergent deliberation loop. Not portable (Gemini has no think tags);
 * the server echoes the prefill, so the harness strips it before scoring. */
const THINK_PREFILL = '</think>\n';

function stripPrefill(ir: string): string {
	return ir.startsWith(THINK_PREFILL) ? ir.slice(THINK_PREFILL.length) : ir;
}

async function runSample(
	promptTemplate: string,
	sample: Sample,
	demo: string | null,
): Promise<EmitRow> {
	const started = performance.now();
	try {
		const prompt =
			demo === null
				? `${promptTemplate}\n---\n${sample.promptInput}\n\nIR:\n`
				: `${promptTemplate}\n---\n${demo}${sample.promptInput}\n\nIR:\n`;
		const messages =
			demo === null
				? [{ role: 'user', content: prompt }]
				: [
						{ role: 'user', content: prompt },
						{ role: 'assistant', content: THINK_PREFILL },
					];
		const [gen, fullTokens] = await Promise.all([
			postJson('/v1/chat/completions', {
				messages,
				temperature: TEMPERATURE,
				max_tokens: MAX_IR_TOKENS,
			}),
			tokenize(sample.reference),
		]);
		const g = gen as {
			choices?: Array<{ message?: { content?: unknown } }>;
			timings?: { predicted_ms?: unknown };
		};
		const raw =
			typeof g.choices?.[0]?.message?.content === 'string'
				? (g.choices[0].message.content as string)
				: '';
		const ir = stripPrefill(raw);
		const irTokens = await tokenize(ir);
		const punt = isPunt(ir);
		const s = punt
			? null
			: scoreGroundedSample(
					sample.reference,
					ir,
					sample.grounding,
					fullTokens,
					irTokens,
				);
		const classTotals: Record<string, number> = {};
		if (s !== null) {
			for (const c of recallByClass(
				extractEntities(sample.reference),
				s.missing,
				extractEntities(sample.grounding),
			)) {
				classTotals[c.class] = c.total;
			}
		}
		const t1 =
			s === null
				? null
				: checkEntityGrounding(
						extractEntities(ir),
						extractEntities(sample.grounding),
					);
		return {
			key: sample.key,
			reference: sample.reference,
			ir,
			fullTokens,
			irTokens,
			ratio: s?.ratio ?? 0,
			recall: s?.recall ?? null,
			missing: s?.missing ?? [],
			classTotals,
			punt,
			tier1pass: t1?.pass ?? true,
			tier1ungrounded: t1?.ungrounded ?? [],
			wallMs: Math.round(performance.now() - started),
			serverMs:
				typeof g.timings?.predicted_ms === 'number'
					? Math.round(g.timings.predicted_ms)
					: null,
			error: null,
		};
	} catch (e) {
		return {
			key: sample.key,
			reference: sample.reference,
			ir: '',
			fullTokens: 0,
			irTokens: 0,
			ratio: 0,
			recall: null,
			missing: [],
			classTotals: {},
			punt: false,
			tier1pass: true,
			tier1ungrounded: [],
			wallMs: Math.round(performance.now() - started),
			serverMs: null,
			error: e instanceof Error ? e.message.slice(0, 200) : String(e),
		};
	}
}

async function main(): Promise<void> {
	const here = dirname(fileURLToPath(import.meta.url));
	const root = join(here, '..', '..');
	const limitArg = Number(process.argv[2]);
	const limit = Number.isInteger(limitArg) && limitArg > 0 ? limitArg : null;
	// Same stratified selection as v3 (25/domain round-robin).
	const { samples } = loadStratified(root, 25, limit);
	const shot = process.argv.includes('--shot');
	const tag = shot ? '-shot' : '';
	const jsonlPath = join(root, 'data', 'derived', `lfm3-emit${tag}.jsonl`);
	if (!process.argv.includes('--force')) {
		let existing = 0;
		try {
			existing = statSync(jsonlPath).size;
		} catch {
			existing = 0;
		}
		if (existing > 0) {
			throw new Error(
				`refusing to overwrite ${jsonlPath} (${existing} bytes) without --force`,
			);
		}
	}
	const promptTemplate = readFileSync(
		join(here, '..', 'prompts', 'ir-grounded-v1.md'),
		'utf8',
	);
	const demo = shot
		? readFileSync(
				join(here, '..', 'prompts', 'ir-grounded-1shot-v1.md'),
				'utf8',
			)
		: null;
	console.log(
		`samples: ${samples.length} (v3 selection, LFM3 emitting${shot ? ', 1-shot+prefill' : ''})`,
	);
	mkdirSync(join(root, 'data', 'derived'), { recursive: true });
	writeFileSync(jsonlPath, '');
	const scored: EmitRow[] = new Array(samples.length);
	let errors = 0;
	let cursor = 0;
	const workers = Array.from({ length: CONCURRENCY }, async () => {
		for (;;) {
			const my = cursor;
			cursor += 1;
			if (my >= samples.length) {
				return;
			}
			const sample = samples[my];
			if (sample === undefined) {
				return;
			}
			scored[my] = await runSample(promptTemplate, sample, demo);
			appendFileSync(jsonlPath, `${JSON.stringify(scored[my])}\n`);
			if (scored[my]?.error !== null && scored[my]?.error !== undefined) {
				errors += 1;
				if (errors <= 3) {
					console.error(
						`sample error ${errors}: ${scored[my]?.error ?? 'unknown'}`,
					);
				}
			}
			if (errors > samples.length * MAX_ERROR_RATE) {
				throw new Error(`error budget exceeded (${errors} failures)`);
			}
		}
	});
	await Promise.all(workers);
	const ok = scored.filter((s) => s.error === null && !s.punt);
	const scores: SampleScore[] = ok.map((s) => ({
		fullTokens: s.fullTokens,
		irTokens: s.irTokens,
		ratio: s.ratio,
		recall: s.recall,
		missing: s.missing,
		emptyIr: s.ir.trim().length === 0,
	}));
	const lite = summarize(scores);
	const classAgg = new Map<string, { total: number; missing: number }>();
	for (const s of ok) {
		for (const [cls, total] of Object.entries(s.classTotals)) {
			const agg = classAgg.get(cls) ?? { total: 0, missing: 0 };
			agg.total += total;
			classAgg.set(cls, agg);
		}
		for (const k of s.missing) {
			const cls = k.split(':')[0] ?? '';
			const agg = classAgg.get(cls) ?? { total: 0, missing: 0 };
			agg.missing += 1;
			classAgg.set(cls, agg);
		}
	}
	const walls = ok.map((s) => s.wallMs).sort((a, b) => a - b);
	const servers = ok
		.map((s) => s.serverMs)
		.filter((v): v is number => v !== null)
		.sort((a, b) => a - b);
	const summary = {
		generatedAt: new Date().toISOString(),
		prompt: 'prompts/ir-grounded-v1.md',
		model: 'kaitchup/LFM3-1.7B-GSQ-GGUF:Q6_K_RCO (local)',
		technique: shot
			? '1-shot demo + </think> assistant prefill (run 018)'
			: 'plain grounded prompt (run 017 baseline)',
		tokenizerNote: 'ratios in LFM3 tokens via /tokenize, not Gemini tokens',
		n: scored.length,
		errors,
		punts: scored.filter((s) => s.punt).length,
		tier1fails: ok.filter((s) => !s.tier1pass).length,
		lite,
		latencyMs: {
			wallP50: walls.length === 0 ? 0 : percentile(walls, 0.5),
			wallMean:
				walls.length === 0
					? 0
					: walls.reduce((a, b) => a + b, 0) / walls.length,
			serverP50: servers.length === 0 ? 0 : percentile(servers, 0.5),
		},
		recallByClass: [...classAgg.entries()]
			.map(([cls, a]) => ({
				class: cls,
				total: a.total,
				missing: a.missing,
				recall: a.total === 0 ? null : (a.total - a.missing) / a.total,
			}))
			.sort((a, b) => (a.class < b.class ? -1 : 1)),
	};
	writeFileSync(
		join(root, 'data', 'derived', `lfm3-emit${tag}-summary.json`),
		`${JSON.stringify(summary, null, 2)}\n`,
	);
	console.log(
		`n=${summary.n} errors=${errors} punts=${summary.punts} tier1fails=${summary.tier1fails}`,
	);
	console.log(
		`recall=${lite.meanRecall === null ? 'n/a' : lite.meanRecall.toFixed(3)} recallN=${lite.recallN} p50ratio=${lite.p50Ratio.toFixed(2)} wallP50=${summary.latencyMs.wallP50}ms`,
	);
}

await main();
